lab.solution:
import java.util.Scanner;

public class Main {
    static int max3(int a, int b, int c) {
        int max = a > b ? a : b;
        return max > c ? max : c;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int c = sc.nextInt();
        System.out.println(max3(a, b, c));
    }
}
